function solve(capacity, operations) {
    const data = new Map();
    const out = [];
    let clock = 0;
    for (const op of operations) {
        clock += 1;
        if (op[0] === 'get') {
            const entry = data.get(op[1]);
            if (entry === undefined) {
                out.push(-1);
            } else {
                entry.freq += 1;
                entry.time = clock;
                out.push(entry.value);
            }
        } else if (capacity > 0) {
            const entry = data.get(op[1]);
            if (entry !== undefined) {
                entry.value = op[2];
                entry.freq += 1;
                entry.time = clock;
            } else {
                if (data.size >= capacity) {
                    let victim = null;
                    for (const [key, e] of data) {
                        if (victim === null || e.freq < victim.e.freq || (e.freq === victim.e.freq && e.time < victim.e.time)) victim = { key, e };
                    }
                    data.delete(victim.key);
                }
                data.set(op[1], { value: op[2], freq: 1, time: clock });
            }
        }
    }
    return out;
}
